/**
 * Native OpenCL bridge (Android only).
 *
 * The actual SHA3-256 kernel is implemented as a Kotlin native module
 * (`RigorOpenCL`) that calls into OpenCL via JNI. This TypeScript module
 * is the JS-side API: it marshals the 80-byte header + bits target to the
 * native side, starts the kernel, and listens for `RigorOpenCLSolution`
 * events emitted by the native module.
 *
 * The native code is generated by `expo prebuild` and lives in
 * `apps/android/android/app/src/main/java/io/secretarrow/rigormobile/`
 * after prebuild. See `docs/MINING.md` for the kernel source.
 */

import { NativeModules, NativeEventEmitter, Platform } from 'react-native';

export interface OpenCLSolution {
  nonce: number;
  digest: string; // 32-byte hex
}

export class RigorOpenCl {
  private emitter?: NativeEventEmitter;
  private listeners = new Set<(s: OpenCLSolution) => void>();

  constructor() {
    if (Platform.OS === 'android' && NativeModules.RigorOpenCL) {
      this.emitter = new NativeEventEmitter(NativeModules.RigorOpenCL);
      this.emitter.addListener('RigorOpenCLSolution', (event: OpenCLSolution) => {
        for (const fn of this.listeners) fn(event);
      });
    }
  }

  isAvailable(): boolean {
    return Platform.OS === 'android' && !!NativeModules.RigorOpenCL;
  }

  onSolution(fn: (s: OpenCLSolution) => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  /** Start the OpenCL kernel. Header is the 80-byte header (with nonce=0). */
  start(headerHex: string, bits: number, startNonce = 0, endNonce = 0xffffffff): void {
    NativeModules.RigorOpenCL?.start?.(headerHex, bits, startNonce, endNonce);
  }

  stop(): void {
    NativeModules.RigorOpenCL?.stop?.();
  }

  /** Returns the hashrate measured on the GPU side, in H/s. */
  async getHashRate(): Promise<number> {
    if (!NativeModules.RigorOpenCL?.getHashRate) return 0;
    return NativeModules.RigorOpenCL.getHashRate();
  }
}

export const openCl = new RigorOpenCl();
